---
import ArrowRightIcon from "@lucide/astro/icons/arrow-right"
import PlusIcon from "@lucide/astro/icons/plus"

import { Button } from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"

const translations = {
  en: {
    dir: "ltr",
    values: {
      button: "Button",
      submit: "Submit",
      delete: "Delete",
      loading: "Loading",
    },
  },
  ar: {
    dir: "rtl",
    values: {
      button: "زر",
      submit: "إرسال",
      delete: "حذف",
      loading: "جاري التحميل",
    },
  },
  he: {
    dir: "rtl",
    values: {
      button: "כפתור",
      submit: "שלח",
      delete: "מחק",
      loading: "טוען",
    },
  },
}

const { dir, values: t } = translations.ar
---

<div class="flex flex-wrap items-center gap-2 md:flex-row" dir={dir}>
  <Button variant="outline">{t.button}</Button>
  <Button variant="destructive">{t.delete}</Button>
  <Button variant="outline">
    {t.submit} <ArrowRightIcon class="rtl:rotate-180" data-icon="inline-end" />
  </Button>
  <Button variant="outline" size="icon" aria-label="Add">
    <PlusIcon />
  </Button>
  <Button variant="secondary" disabled>
    <Spinner data-icon="inline-start" />
    {t.loading}
  </Button>
</div>
